<?php use App\Core\Security; ?><h4>جستجو و فیلتر پیشرفته</h4><form class="card card-body mb-3"><div class="row g-2"><div class="col-md-3"><input name="q" value="<?=Security::e($q)?>" class="form-control" placeholder="کد یا نام"></div><div class="col-md-2"><select name="category_id" class="form-select"><option value="0">همه دسته‌ها</option><?php foreach($categories as $x):?><option value="<?=$x['id']?>" <?=$category==$x['id']?'selected':''?>><?=Security::e($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select name="unit_id" class="form-select"><option value="0">همه واحدها</option><?php foreach($units as $x):?><option value="<?=$x['id']?>" <?=$unit==$x['id']?'selected':''?>><?=Security::e($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select name="importance" class="form-select"><option value="0">همه اهمیت‌ها</option><option value="1" <?=$importance===1?'selected':''?>>عادی</option><option value="2" <?=$importance===2?'selected':''?>>مهم</option><option value="3" <?=$importance===3?'selected':''?>>بحرانی</option></select></div><div class="col-md-3"><select name="status" class="form-select"><option value="active" <?=$status==='active'?'selected':''?>>فعال</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>غیرفعال</option><option value="all" <?=$status==='all'?'selected':''?>>همه</option></select></div><div class="col-md-2"><input type="number" name="age" value="<?=Security::e($age)?>" class="form-control" placeholder="سن قیمت (روز)"></div><div class="col-md-2"><input name="min_price" value="<?=Security::e($min)?>" class="form-control" placeholder="حداقل قیمت"></div><div class="col-md-2"><input name="max_price" value="<?=Security::e($max)?>" class="form-control" placeholder="حداکثر قیمت"></div><div class="col-md-2"><button class="btn btn-primary w-100">جستجو</button></div></div></form><div class="card card-body mb-3"><form method="post" action="/pricing/public/search/save-filter" class="row g-2"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="col-md-4"><input name="name" class="form-control" placeholder="نام فیلتر"></div><input type="hidden" name="filter_json" value="<?=Security::e(json_encode($_GET,JSON_UNESCAPED_UNICODE))?>"><div class="col-md-2"><button class="btn btn-outline-primary">ذخیره فیلتر فعلی</button></div></form><?php foreach($filters as $f):?><span class="badge text-bg-light border me-1"><?=Security::e($f["name"])?></span><?php endforeach;?></div><div class="table-responsive"><table class="table table-bordered align-middle"><thead><tr><th>کد</th><th>محصول</th><th>دسته</th><th>واحد</th><th>اهمیت</th><th>آخرین قیمت</th><th>آخرین تاریخ</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=Security::e($r['product_code'])?></td><td><?=Security::e($r['product_name'])?></td><td><?=Security::e($r['category_name'])?></td><td><?=Security::e($r['unit_name'])?></td><td><?=['','عادی','مهم','بحرانی'][(int)$r['importance']]?></td><td><?=number_format((float)$r['latest_unit_price'],2)?></td><td><?=$r['latest_date']?Security::e(\App\Support\Jalali::fromGregorian($r['latest_date'])):'—'?></td><td><a class="btn btn-sm btn-outline-primary" href="/pricing/public/prices/<?=$r['id']?>/edit">ویرایش</a></td></tr><?php endforeach;?></tbody></table></div>